function previewChatMessages(msgs, fromIdx){
  const CONTENT=600;
  const KEEP=10;
  const list=Array.isArray(msgs)?msgs:[];
  const slim=(m)=>{
    const raw=m&&typeof m==='object'&&!Array.isArray(m)?m:{};
    const c=raw.content;
    let text='';
    if(typeof c==='string') text=c;
    else if(c==null) text='';
    else { try{text=JSON.stringify(c);}catch(e){text=String(c);} }
    if(text.length>CONTENT) text=text.slice(0,CONTENT-1)+'…';
    const out={role:String(raw.role||''),content:text};
    if(raw.tool_call_id) out.tool_call_id=String(raw.tool_call_id);
    if(Array.isArray(raw.tool_calls)&&raw.tool_calls.length) out.tool_calls=raw.tool_calls.length;
    return out;
  };
  const all=list.map(slim);
  const start=Math.max(0,Number(fromIdx)||0);
  let picked=start>0?all.slice(start):all.slice();
  let omitted=0;
  if(start>0&&all[0]&&all[0].role==='system'){
    omitted=Math.max(0,start-1);
    picked=[all[0],...(omitted?[{role:'omitted',count:omitted}]:[]),...picked];
  }
  if(picked.length>KEEP){
    omitted += picked.length-KEEP;
    picked=[picked[0],{role:'omitted',count:omitted},...picked.slice(-(KEEP-2))];
  }
  const preview={messages:picked};
  if(omitted) preview.omitted=omitted;
  return preview;
}
const SYSTEM="Ты — решатель агента Demo Agent (демонстрационный агент-шаблон). Ты читаешь задачу инженера и вызываешь один инструмент; считают инструменты, ты сам ничего не вычисляешь и SCHEDULE не пишешь.\n\nsession_id привязан workflow: никогда не передавай session_id и обёртку args/input.\n\nКакой инструмент когда:\n- Задача просит посчитать или перечислить скважины (в тексте есть их номера или есть факты предыдущих агентов) → count_wells. Один вызов.\n- Задача просит запустить расчёт, прогон, долгую операцию или явно упоминает демонстрацию долгой работы → start_long_job с коротким русским названием расчёта в label. Один вызов, после ответа in_progress — STOP.\n- Из задачи непонятно, что считать, и в ней нет скважин → ask_engineer одним вопросом обычной русской фразой.\n\nОтветы инструментов:\n- ok:false, code:no_wells_found — это тебе, не инженеру: спроси инженера через ask_engineer, о каких скважинах речь.\n- ok:false, code:question_not_human — переформулируй вопрос прозой и вызови ask_engineer снова.\n- status completed / in_progress / needs_input — результат зафиксирован, STOP.\n\nНе придумывай скважины и числа — только из ответов инструментов. Заверши одним коротким фактическим предложением по-русски.\n";
